;(function(){
  var INTERVAL=60;
  var css=document.createElement("style");
  css.textContent=`
    #refresh-bar-container{display:flex;align-items:center;gap:12px;font-family:'JetBrains Mono','Fira Code','SF Mono',monospace;font-size:10px;color:#444;padding:0 4px;margin-bottom:20px;animation:slideUp 0.6s ease 0.25s both}
    #refresh-bar-track{flex:1;height:3px;background:rgba(100,100,140,0.1);border-radius:2px;overflow:hidden}
    #refresh-bar-fill{height:100%;width:100%;border-radius:2px;background:linear-gradient(90deg,#A78BFA,#00ccff);transform-origin:left;box-shadow:0 0 6px rgba(167,139,250,0.3);transition:none}
    #refresh-bar-fill.depleting{background:linear-gradient(90deg,#ff9100,#ff6d00);box-shadow:0 0 6px rgba(255,145,0,0.3)}
    #refresh-bar-fill.critical{background:linear-gradient(90deg,#ff5252,#d50000);box-shadow:0 0 6px rgba(255,82,82,0.3)}
    #refresh-countdown{min-width:28px;text-align:right;font-variant-numeric:tabular-nums;color:#333}
    #refresh-label{white-space:nowrap;color:#333;letter-spacing:1px;text-transform:uppercase}
    @keyframes bestPulse{0%,100%{box-shadow:0 0 20px #00ff8844,0 0 40px #00ff8822}50%{box-shadow:0 0 30px #00ff8866,0 0 60px #00ff8833}}
    @keyframes worstPulse{0%,100%{box-shadow:0 0 20px #ff446644,0 0 40px #ff446622}50%{box-shadow:0 0 30px #ff446666,0 0 60px #ff446633}}
    .sparkle{position:fixed;pointer-events:none;z-index:10000;border-radius:50%;animation:sparkleFade 0.6s ease-out forwards}
    @keyframes chartFadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@keyframes sparkleFade{0%{transform:scale(1);opacity:1}100%{transform:scale(0);opacity:0}}
  `;
  document.head.appendChild(css);

  /* --- REFRESH BAR --- */
  function initRefreshBar(){
    var mainContainer=document.querySelector('[style*="max-width"]');
    if(!mainContainer)return setTimeout(initRefreshBar,200);
    var children=mainContainer.children;
    var tickerEl=null;
    for(var i=0;i<children.length;i++){
      var s=children[i].getAttribute("style")||"";
      if(s.indexOf("overflow")!==-1 && s.indexOf("hidden")!==-1 && children[i].querySelector('[style*="ticker"]')){
        tickerEl=children[i];break;
      }
    }
    if(!tickerEl)return setTimeout(initRefreshBar,200);
    var bar=document.createElement("div");
    bar.id="refresh-bar-container";
    bar.innerHTML='<span id="refresh-label">next update</span><div id="refresh-bar-track"><div id="refresh-bar-fill"></div></div><span id="refresh-countdown">60s</span>';
    tickerEl.parentNode.insertBefore(bar,tickerEl);
    var fill=document.getElementById("refresh-bar-fill");
    var countdown=document.getElementById("refresh-countdown");
    var start=Date.now();
    function clickRefresh(){
      var spans=document.querySelectorAll("span");
      for(var k=0;k<spans.length;k++){
        var txt=spans[k].textContent.trim();
        if(txt==="⟳ REFRESH"||txt==="⏳ SYNCING"){spans[k].click();break;}
      }
    }
    function update(){
      var elapsed=(Date.now()-start)/1000;
      var remaining=Math.max(0,INTERVAL-elapsed);
      var pct=remaining/INTERVAL;
      fill.style.transform="scaleX("+pct+")";
      fill.className=remaining<=10?"critical":remaining<=20?"depleting":"";
      countdown.textContent=Math.ceil(remaining)+"s";
      if(remaining<=0){clickRefresh();start=Date.now();}
      requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  /* --- SPARKLE CURSOR TRAIL --- */
  var sparkleColors=["#A78BFA","#00ff88","#00ccff","#F59E0B","#EC4899","#FBBF24"];
  var sparkleThrottle=0;
  document.addEventListener("mousemove",function(e){
    var now=Date.now();
    if(now-sparkleThrottle<50)return;
    sparkleThrottle=now;
    var s=document.createElement("div");
    s.className="sparkle";
    var size=Math.random()*4+2;
    var color=sparkleColors[Math.floor(Math.random()*sparkleColors.length)];
    s.style.cssText="left:"+(e.clientX-size/2)+"px;top:"+(e.clientY-size/2)+"px;width:"+size+"px;height:"+size+"px;background:"+color+";box-shadow:0 0 "+size*2+"px "+color+";";
    document.body.appendChild(s);
    setTimeout(function(){s.remove()},600);
  });

  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",function(){setTimeout(initRefreshBar,500)})}
  else{setTimeout(initRefreshBar,500)}
})();
